/* 영수증 등록 */
INSERT INTO RECPT
     ( MBR_SN
     , ATCH_FILE_SN
     , OCR_PRCS_STTS_CD
     , OCR_DMND_SRC_CD
     , REG_DT
     , MDFCN_DT )
